import yaml
import re

def generate_endpoint_table(openapi_yaml):
    """
    Convert OpenAPI YAML to a markdown table of endpoints.
    """
    # Parse the YAML file
    try:
        spec = yaml.safe_load(openapi_yaml)
    except Exception as e:
        raise ValueError(f"Error parsing YAML: {str(e)}")

    # Extract endpoints
    endpoints = []

    # Check for paths in the OpenAPI specification
    if 'paths' in spec:
        for path, path_item in spec['paths'].items():
            for method, method_item in path_item.items():
                if 'summary' in method_item:
                    endpoints.append({
                        'path': path,
                        'method': method,
                        'description': method_item['summary']
                    })
                elif 'description' in method_item:
                    endpoints.append({
                        'path': path,
                        'method': method,
                        'description': method_item['description']
                    })

    # Check for components if paths are not found
    if not endpoints and 'components' in spec:
        # Look for operations in components
        if 'schemas' in spec['components']:
            # This is a fallback - OpenAPI paths are typically defined in paths
            # We'll just return a message indicating no endpoints found
            return "No endpoints found in the OpenAPI specification.\n\nPlease ensure the OpenAPI specification has a 'paths' section with operation definitions."

    # Generate markdown table
    if not endpoints:
        return "No endpoints found in the OpenAPI specification.\n\nPlease ensure the OpenAPI specification has a 'paths' section with operation definitions."

    table = "| Path | Method | Description |\n|------|--------|-------------|\n"
    for endpoint in endpoints:
        table += f"| {endpoint['path']} | {endpoint['method']} | {endpoint['description']} |\n"

    return table

def main():
    """
    Main function to run the tool.
    """
    # Read the OpenAPI YAML file
    with open('openapi.yaml', 'r') as file:
        yaml_content = file.read()

    # Generate the markdown table
    markdown_table = generate_endpoint_table(yaml_content)

    # Return the markdown table
    return markdown_table

if __name__ == "__main__":
    print(main())

